import { DEMO_HOTEL } from "../src/data/demo-hotel";
import { DEMO_SITE } from "../src/data/demo-site";
import { hotelSiteSchema } from "../src/lib/site/schema";

/** SQL that loads the demo hotel's website content. Kept in sync by a test. */
export function buildSiteSeedSql(): string {
  const content = JSON.stringify(hotelSiteSchema.parse(DEMO_SITE));
  // Dollar quoting: the JSON may contain single quotes (e.g. "Prophet's").
  return [
    "-- Generated by scripts/build-site-seed.ts from src/data/demo-site.ts. Do not edit by hand.",
    "-- Website content for the fictional demo hotel.",
    "insert into public.hotel_sites (hotel_id, content) values (",
    `  '${DEMO_HOTEL.id}',`,
    `  $site$${content}$site$::jsonb`,
    ") on conflict (hotel_id) do update set content = excluded.content, updated_at = now();",
    "",
  ].join("\n");
}

/**
 * SQL that creates or replaces one hotel's website content, found by slug.
 * Used by `npm run site:check` in the hotel onboarding workspace (stage 03).
 */
export function buildSiteUpsertSql(slug: string, content: unknown): string {
  if (!/^[a-z0-9-]{2,60}$/.test(slug)) throw new Error(`Not a valid hotel slug: ${slug}`);
  const json = JSON.stringify(hotelSiteSchema.parse(content));
  if (json.includes("$site$")) throw new Error("Content may not contain the text $site$");
  return [
    `-- Website content for hotel '${slug}'. Generated by npm run site:check. Do not edit by hand.`,
    "insert into public.hotel_sites (hotel_id, content)",
    `select id, $site$${json}$site$::jsonb from public.hotels where slug = '${slug}'`,
    "on conflict (hotel_id) do update set content = excluded.content, updated_at = now();",
    "",
  ].join("\n");
}
